import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const request=JSON.parse(readFileSync('_work/gpu-owner-recovery/cuda-input-request.json','utf8'));
const closure=JSON.parse(readFileSync('_work/gpu-owner-recovery/closure.json','utf8'));
const metadata=JSON.parse(readFileSync(request.observedBlockerReceipt,'utf8'));
const lock=Bun.TOML.parse(readFileSync('Cargo.lock','utf8'));
const exact=lock.package.find(item=>item.name==='cubek-fft'&&item.version==='0.3.1');
if(!exact||request.requestedArtifacts.length!==1)throw Error('EXACT_ONE_LOCKED_INPUT_REQUIRED');
const artifact=request.requestedArtifacts[0];
if(artifact.sha256!==exact.checksum||artifact.byteLength!==56719||artifact.url!=='https://static.crates.io/crates/cubek-fft/cubek-fft-0.3.1.crate')throw Error('REQUEST_IDENTITY_MISMATCH');
if(request.acquisitionAuthorized!==false||request.cudaCompilationAuthorizedByThisRequest!==false||request.dependencyBuildScriptExecutionAuthorizedByThisRequest!==false||request.hostOrContainerOperationsAuthorized!==false||request.trainingReady!==false)throw Error('AUTHORITY_BROADENED');
if(metadata.status!=='FAIL'||metadata.sourceChanged!==false||metadata.sourceKind!=='ACTUAL_WORKSPACE_NOT_SURROGATE'||metadata.compilationPerformed!==false||metadata.buildScriptsExecuted!==false||!metadata.argv.includes('--locked')||!metadata.argv.includes('--offline'))throw Error('ACTUAL_OFFLINE_FAILURE_REQUIRED');
for(const source of metadata.sources){if(hash(readFileSync(source.path))!==source.sha256)throw Error('METADATA_INPUT_CHANGED:'+source.path);}
for(const stream of metadata.streams){const bytes=readFileSync(stream.path);if(hash(bytes)!==stream.sha256||bytes.length!==stream.bytes)throw Error('FAILED_STREAM_CHANGED');}
if(closure.sourceHandoffIsTerminal!==false||closure.overarchingObjective!=='trainingReady:true'||closure.newOperationalOrAcquisitionAuthorityGranted!==false)throw Error('PREMATURE_TERMINAL_SCOPE');
console.log(JSON.stringify({status:'PASS',exactInput:{name:artifact.name,version:artifact.version,byteLength:artifact.byteLength,sha256:artifact.sha256},actualOfflineMetadataFailurePreserved:true,lockAndSourceInputsUnchanged:true,sourceHandoffIsTerminal:false,acquisitionAuthorized:false,trainingReady:false},null,2));
